import{d as l,C as r,o,c as s,j as a,a as i,E as d,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"荀子·第32篇·尧问","description":"《荀子·尧问》——以问答和轶事收束治道、处世与人物评论。","frontmatter":{"title":"荀子·第32篇·尧问","description":"《荀子·尧问》——以问答和轶事收束治道、处世与人物评论。","category":"guide","aliases":["荀子尧问","荀子第32篇"],"source":["维基文库《荀子/堯問篇》，修订号 1392646"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/xunzi/chapter-32.md","filePath":"lizhimingde/xunzi/chapter-32.md","lastUpdated":1794362429000}'),p={name:"lizhimingde/xunzi/chapter-32.md"},x=l({...p,setup(u){const t=[{id:"p001",sentences:[["尧问于舜曰：“我欲致天下，为之奈何？”对曰：“执一无失，行微无怠，忠信无倦，而天下自来。执一如天地，行微如日月，忠诚盛于内，贲于外，形于四海。天下其在一隅邪！夫有何足致也？”"]]},{id:"p002",sentences:[["魏武侯谋事而当，群臣莫能逮，退朝而有喜色。吴起进曰：“亦尝有以楚庄王之语闻于左右者乎？”武侯曰：“楚庄王之语何如？”吴起对曰：“楚庄王谋事而当，群臣莫能逮，退朝而有忧色。申公巫臣进问曰：‘王朝而有忧色，何也？’庄王曰：‘不穀谋事而当，群臣莫能逮，是以忧也。其在中蘬之言也，曰：“诸侯自为得师者王，得友者霸，得疑者存，自为谋而莫己若者亡。”今以不穀之不肖而群臣莫能逮，吾国几于亡乎！是以忧也。’楚庄王以忧，而君以憙。”武侯逡巡再拜曰：“天使夫子振寡人之过也。”"]]},{id:"p003",sentences:[["伯禽将归于鲁，周公谓伯禽之傅曰：“汝将行，盍志而子美德乎？”对曰：“其为人宽，好自用，以慎。此三者，其美德已。”周公曰：“呜呼！以人恶为美德乎？君子好以道德，故其民归道。彼其宽也，出无辨矣，女又美之。彼其好自用也，是所以窭小也。君子力如牛，不与牛争力；走如马，不与马争走；知如士，不与士争知。彼争者，均者之气也，女又美之。彼其慎也，是其所以浅也。闻之曰：无越逾不见士。见士问曰：‘无乃不察乎？’不闻，即物少至，少至则浅。彼浅者，贱人之道也，女又美之。吾语女：我，文王之为子，武王之为弟，成王之为叔父。吾于天下不贱矣，然而吾所执贽而见者十人，还贽而相见者三十人，貌执之士者百有馀人，欲言而请毕事者千有馀人，于是吾仅得三士焉，以正吾身，以定天下。吾所以得三士者，亡于十人与三十人中，乃在百人与千人之中。故上士吾薄为之貌，下士吾厚为之貌。人人皆以我为越逾好士，然故士至，士至而后见物，见物然后知其是非之所在。戒之哉！女以鲁国骄人，几矣！夫仰禄之士犹可骄也，正身之士不可骄也。彼正身之士，舍贵而为贱，舍富而为贫，舍佚而为劳，颜色黎黑而不失其所，是以天下之纪不息，文章不废也。”"]]},{id:"p004",sentences:[["语曰：“缯丘之封人，见楚相孙叔敖曰：‘吾闻之也：处官久者士妒之，禄厚者民怨之，位尊者君恨之。为相国有此三者而不得罪于楚之士民，何也？’孙叔敖曰：‘吾三相楚而心愈卑，每益禄而施愈博，位滋尊而礼愈恭，是以不得罪于楚之士民也。’”"]]},{id:"p005",sentences:[["子贡问于孔子曰：“赐为人下而未知也。”孔子曰：“为人下者乎？其犹土也？深抇之而得甘泉焉，树之而五谷蕃焉，草木殖焉，禽兽育焉，生则立焉，死则入焉，多其功而不息。为人下者，其犹土也。”"]]},{id:"p006",sentences:[["昔虞不用宫之奇而晋并之，莱不用子马而齐并之，纣刳王子比干而武王得之。不亲贤用知，故身死国亡也。"]]},{id:"p007",sentences:[["为说者曰：“孙卿不及孔子。”是不然。孙卿迫于乱世，䲡于严刑，上无贤主，下遇曓秦，礼义不行，教化不成，仁者绌约，天下冥冥，行全剌之，诸侯大倾。当是时也，知者不得虑，能者不得治，贤者不得使。故君上蔽而无睹，贤人距而不受。然则孙卿怀将圣之心，蒙佯狂之色，视天下以愚。《诗》曰：“既明且哲，以保其身。”此之谓也。是其所以名声不白，徒与不众，光辉不博也。今之学者，得孙卿之遗言馀教，足以为天下法式表仪，所存者神，所过者化。观其善行，孔子弗过，世不详察，云非圣人，奈何！天下不治，孙卿不遇时也。德若尧、禹，世少知之。方术不用，为人所疑。其知至明，循道正行，足以为纪纲。呜呼！贤哉！宜为帝王。天地不知，善桀、纣，杀贤良。比干剖心，孔子拘匡；接舆避世，箕子佯狂；田常为乱，阖闾擅强。为恶得福，善者有殃。今为说者又不察其实，乃信其名。时世不同，誉何由生？不得为政，功安能成？志修德厚，孰谓不贤乎！"]]}];return(c,e)=>{const n=r("DaoTextReading");return o(),s("div",null,[e[0]||(e[0]=a("h1",{id:"荀子·第32篇·尧问",tabindex:"-1"},[i("荀子·第32篇·尧问 "),a("a",{class:"header-anchor",href:"#荀子·第32篇·尧问","aria-label":'Permalink to "荀子·第32篇·尧问"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇讨论：以问答和轶事收束治道、处世与人物评论。",-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,"原文已录入；段级白话、字词点查与三问解读待逐篇补充。原文录入不等于解读完成。")],-1)),e[3]||(e[3]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),e[4]||(e[4]=a("p",null,"经典阅读保留段落；切换「竹简」可连续通读。此阶段按来源自然段呈现，不为未整理的段落预填释义。",-1)),d(n,{sections:t,"default-mode":"classic",tone:"ink",colophon:"荀子 · 尧问","aria-label":"荀子·尧问原文"}),e[5]||(e[5]=h("",8))])}}});export{f as __pageData,x as default};
